import{_ as s,o as i,c as t,a6 as a}from"./chunks/framework.Dtv7txdI.js";const k=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"v1/server/deployment/index.md","filePath":"v1/server/deployment/index.md","lastUpdated":1787648967000}'),n={name:"v1/server/deployment/index.md"};function o(l,e,r,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to “Deployment”">​</a></h1><p>The operational surface of a running Nitr process: how to tell whether it is healthy, how to reload it, and how to stop it without cutting requests.</p><h2 id="the-whole-surface-in-one-table" tabindex="-1">The whole surface, in one table <a class="header-anchor" href="#the-whole-surface-in-one-table" aria-label="Permalink to “The whole surface, in one table”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Mechanism</th></tr></thead><tbody><tr><td>Is the process alive?</td><td><code>GET /healthz</code> → <code>200 ok</code>, answered in Rust, never touches a Lua state</td></tr><tr><td>Should it get traffic?</td><td><code>GET /readyz</code> → <code>200 ok</code>, flips to <code>503 draining</code> the moment a graceful shutdown starts</td></tr><tr><td>Stop it</td><td><code>SIGTERM</code> — stop accepting → flip readiness → drain for <code>[shutdown] grace</code> (+ <code>stream_grace</code>) → exit. A truncated drain exits non-zero</td></tr><tr><td>Reload it</td><td><code>SIGHUP</code>, or <a href="./../cli#reload"><code>nitr reload</code></a> (finds the process via its <code>pidfile</code>)</td></tr><tr><td>Machine-readable logs</td><td><code>[log] format = &quot;json&quot;</code> — one object per line, request and error fields as real keys</td></tr><tr><td>Which config value won?</td><td><code>nitr check --print-config</code></td></tr><tr><td>Single-file deploy</td><td><a href="./single-file"><code>nitr build --output myapp</code></a></td></tr></tbody></table><h2 id="health-probes" tabindex="-1">Health probes <a class="header-anchor" href="#health-probes" aria-label="Permalink to “Health probes”">​</a></h2><p>Both endpoints are <strong>owned by Rust</strong>. A handler cannot influence them, which is the point: an application cannot report itself healthy through a broken handler.</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">health</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">liveness = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/healthz&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">readiness = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/readyz&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Endpoint</th><th>Answers</th><th>Meaning</th></tr></thead><tbody><tr><td><code>/healthz</code></td><td><code>200 ok</code></td><td>The process is alive. Never touches a Lua state, so it stays fast under load.</td></tr><tr><td><code>/readyz</code></td><td><code>200 ok</code> / <code>503 draining</code></td><td>Whether this instance should receive traffic.</td></tr></tbody></table><p><strong>Readiness flipping before requests can fail is what makes a rolling deploy hitless.</strong> The endpoint reports <code>503 draining</code> while in-flight work finishes, so the load balancer moves traffic <em>first</em>.</p><h3 id="keeping-probes-off-the-public-port" tabindex="-1">Keeping probes off the public port <a class="header-anchor" href="#keeping-probes-off-the-public-port" aria-label="Permalink to “Keeping probes off the public port”">​</a></h3><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">health</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:9090&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # probes only; the app never answers here</span></span></code></pre></div><h2 id="graceful-shutdown" tabindex="-1">Graceful shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to “Graceful shutdown”">​</a></h2><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shutdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">grace = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # seconds for ordinary in-flight requests</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stream_grace = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # extra, spent only if a stream is still live</span></span></code></pre></div><p>On <code>SIGTERM</code> or <code>SIGINT</code>:</p><ol><li>Stop accepting new connections.</li><li>Flip <code>/readyz</code> to <code>503 draining</code>.</li><li>Let in-flight requests finish, within <code>grace</code>.</li><li>Give live streams <code>stream_grace</code> extra seconds.</li><li>Exit.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">Your supervisor must wait longer than the drain</p><p></p><p><code>TimeoutStopSec</code> (systemd) or <code>--time</code> (Docker) must exceed <code>grace + stream_grace</code> — 35 seconds by default. Set below that, the supervisor <code>SIGKILL</code>s the process mid-drain, cutting exactly the requests graceful shutdown exists to protect.</p></div><p>A drain that runs out of time <strong>exits non-zero</strong>, because a cut request is not a clean shutdown. Configure <code>Restart=on-failure</code> accordingly.</p><h2 id="zero-downtime-reload" tabindex="-1">Zero-downtime reload <a class="header-anchor" href="#zero-downtime-reload" aria-label="Permalink to “Zero-downtime reload”">​</a></h2><p><code>SIGHUP</code> rebuilds the Lua runtime pool: the config script re-runs and the handler recompiles, while live connections keep being served. It is <strong>not</strong> a restart — the process, its listener and its keep-alive connections all survive.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # via the configured pidfile</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -HUP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # the same thing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # ExecReload maps to it</span></span></code></pre></div><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pidfile = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/run/nitr/nitr.pid&quot;</span></span></code></pre></div><p>The pidfile is written only once the build succeeded and removed at exit — including the error path — so a crashed server never leaves a stale pid behind for <code>reload</code> to signal.</p><h2 id="deployment-models" tabindex="-1">Deployment models <a class="header-anchor" href="#deployment-models" aria-label="Permalink to “Deployment models”">​</a></h2><h3 id="one-binary-plus-files" tabindex="-1">One binary plus files <a class="header-anchor" href="#one-binary-plus-files" aria-label="Permalink to “One binary plus files”">​</a></h3><p>Copy <code>nitr</code>, <code>nitr.toml</code> and the application directory onto the machine. Run it under <a href="./systemd">systemd</a>. Deploys are an <code>rsync</code> plus <code>systemctl reload</code>.</p><h3 id="one-self-contained-binary" tabindex="-1">One self-contained binary <a class="header-anchor" href="#one-self-contained-binary" aria-label="Permalink to “One self-contained binary”">​</a></h3><p><a href="./single-file"><code>nitr build --output myapp</code></a> appends the entire application to the executable. A deploy is one file. The database stays external, on purpose.</p><h3 id="a-container" tabindex="-1">A container <a class="header-anchor" href="#a-container" aria-label="Permalink to “A container”">​</a></h3><p><a href="./docker">Docker</a>, with the database on a volume and Nitr as PID 1 so it actually receives the <code>SIGTERM</code>.</p><h2 id="the-deploy-sequence-that-works" tabindex="-1">The deploy sequence that works <a class="header-anchor" href="#the-deploy-sequence-that-works" aria-label="Permalink to “The deploy sequence that works”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Validate the artifact before it goes anywhere near production.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Apply the schema ONCE — not from every starting instance.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Roll the instances. Readiness moves the traffic for you.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or your orchestrator&#39;s rollout</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">Migrate separately, always</p><p></p><p>Applying schema changes at boot means a rolling deployment has two instances racing to change the same schema, each believing it is alone. That is why <code>nitr migrate</code> is its own command — and why the server refuses to start while a migration is pending, so a mistake here is loud.</p></div><h2 id="behind-a-reverse-proxy" tabindex="-1">Behind a reverse proxy <a class="header-anchor" href="#behind-a-reverse-proxy" aria-label="Permalink to “Behind a reverse proxy”">​</a></h2><p>Nitr does not terminate TLS. Put nginx, Caddy, HAProxy or a cloud load balancer in front of it, and bind Nitr privately:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">listen = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:3000&quot;</span></span></code></pre></div><p>Two settings become safe to enable <strong>only</strong> behind a proxy that sanitizes the relevant headers:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trust_request_id = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # accept an inbound X-Request-ID</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rate_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trust_forwarded_for = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # key the limiter by X-Forwarded-For</span></span></code></pre></div><p>Turned on without such a proxy, a client picks its own request id and its own rate-limit key.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to “Backups”">​</a></h2><p>The database is the only state, and WAL means it is three files:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/app.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;VACUUM INTO &#39;backup-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F).db&#39;&quot;</span></span></code></pre></div><p><code>VACUUM INTO</code> is safe while the server is running. Copying <code>app.db</code> alone is not — see <a href="./../database#why-wal-matters-here-specifically">Database → Why WAL matters</a>.</p><h2 id="capacity" tabindex="-1">Capacity <a class="header-anchor" href="#capacity" aria-label="Permalink to “Capacity”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it bounds</th></tr></thead><tbody><tr><td><code>workers</code></td><td>Concurrent dynamic requests — this <strong>is</strong> your concurrency limit</td></tr><tr><td><code>max_streams</code></td><td>Concurrent streaming/SSE responses (each holds a state for its lifetime)</td></tr><tr><td><code>[limits] max_connections</code></td><td>Concurrent TCP connections</td></tr><tr><td><code>[limits] pool_wait_ms</code></td><td>How long a request queues before being shed with <code>503</code></td></tr></tbody></table><p>At debug level, <code>pool_checkout</code>&#39;s <code>wait_ms</code> and <code>outcome</code> (<code>hit</code> / <code>shed</code>) tell you whether the pool is the bottleneck before your users do.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to “Monitoring”">​</a></h2><p>There is no metrics endpoint yet (<a href="./../security#known-weaknesses">known limitation</a>). Ship the JSON logs and alert on:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Where</th></tr></thead><tbody><tr><td>Error rate</td><td><code>status &gt;= 500</code> on the <code>request</code> span</td></tr><tr><td>Latency</td><td><code>time.busy</code> on the <code>request</code> span</td></tr><tr><td>Overload</td><td><code>outcome = &quot;shed&quot;</code> on <code>pool_checkout</code>, or <code>status = 503</code></td></tr><tr><td>Rate limiting</td><td><code>status = 429</code></td></tr><tr><td>Recycled states</td><td><code>outcome = &quot;rebuilt&quot;</code> from the pool</td></tr></tbody></table><p>See <a href="./../logging">Logging</a>.</p>`,49)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
